// Converts the canonical essay script (markdown) into the essay episode
// production representation consumed by Video Factory.
//
// The markdown file is the single human-edited source of truth. This file is
// regenerated by this converter; never hand-edit the generated JSON.
//
// Usage:
//   node scripts/essay-script-to-lesson.mjs inbox/ESSY-0001/script.md \
//     [--episode ESSY-0001] [--title "..."] [--images scene01.png,...] [--out lesson.json]
import {mkdir, readFile, writeFile} from "node:fs/promises";
import path from "node:path";
import process from "node:process";

const DEFAULT_IMAGES = [
  "scene01.png",
  "scene02.png",
  "scene03.png",
  "scene04.png",
  "scene05.png",
  "scene06.png",
];

function parseArguments(argv) {
  const args = {positional: [], images: DEFAULT_IMAGES};
  for (let index = 0; index < argv.length; index += 1) {
    const argument = argv[index];
    if (argument === "--episode") args.episode = argv[++index];
    else if (argument === "--title") args.title = argv[++index];
    else if (argument === "--images") args.images = argv[++index].split(",");
    else if (argument === "--out") args.out = argv[++index];
    else if (argument === "--voice") args.voice = argv[++index];
    else if (argument === "--rate") args.rate = argv[++index];
    else if (argument === "--pitch") args.pitch = argv[++index];
    else args.positional.push(argument);
  }
  return args;
}

function parseScript(markdown) {
  const normalized = String(markdown).replaceAll("\r\n", "\n");
  const heading = /^#\s*(.+)$/m.exec(normalized);
  const titleLine = heading?.[1]?.trim() ?? "";
  const episodeMatch = /^ESSY-\d{4}$/.exec(
    /^(ESSY-\d{4})/m.exec(normalized)?.[1] ?? "",
  );

  // Each narration block is a "## N### — Heading" section; body lines are
  // preserved verbatim (approved text is never rewritten here).
  const marks = [...normalized.matchAll(/^##\s+(N\d{3})\s*[—–-]\s*(.+)\s*$/gm)];
  const sections = marks.map((mark, index) => {
    const start = mark.index + mark[0].length;
    const end =
      index + 1 < marks.length ? marks[index + 1].index : normalized.length;
    const raw = normalized.slice(start, end);
    const rule = raw.indexOf("\n---");
    const bodySource = rule >= 0 ? raw.slice(0, rule) : raw;
    const body = bodySource.replace(/^\s*\n+/, "").replace(/\n+\s*$/, "");
    if (!body.trim()) {
      throw new Error(`${mark[1]} has an empty narration body.`);
    }
    return {
      id: mark[1].toLowerCase(),
      heading: mark[2].trim(),
      body,
    };
  });

  return {titleLine, episodeId: episodeMatch?.[1] ?? null, sections};
}

async function main() {
  const args = parseArguments(process.argv.slice(2));
  const input = args.positional[0];
  if (!input) {
    throw new Error("Usage: essay-script-to-lesson.mjs <script.md> [options]");
  }
  const inputPath = path.resolve(input);
  const markdown = await readFile(inputPath, "utf8");
  const parsed = parseScript(markdown);
  if (parsed.sections.length === 0) {
    throw new Error("No '## N### — Heading' narration blocks found.");
  }

  const outDir = path.dirname(inputPath);
  const episode =
    args.episode ?? parsed.episodeId ?? path.basename(outDir).toUpperCase();
  if (!/^ESSY-\d{4}$/.test(episode)) {
    throw new Error(`Could not determine a valid ESSY episode id ("${episode}").`);
  }
  const fallbackTitle = /^#.*?—\s*(.+)$/.exec(`# — ${parsed.titleLine}`)?.[1];
  const title =
    args.title ??
    fallbackTitle?.trim() ??
    parsed.titleLine.replace(/^ESSY-\d{4}\s*[—–-]\s*/, "").trim();
  if (!title) throw new Error("Could not determine the episode title.");

  const episodeJson = {
    schemaVersion: "1.0",
    episode,
    series: "ESSY",
    subtype: "essay",
    title,
    language: "en",
    renderMode: "essay-narration",
    topic: null,
    sources: [],
    ...(args.voice || args.rate
      ? {
          voice: {
            provider: "edge",
            ...(args.voice ? {voice: args.voice} : {}),
            ...(args.rate ? {rate: args.rate} : {}),
            ...(args.pitch ? {pitch: args.pitch} : {}),
          },
        }
      : {}),
    sections: parsed.sections.map((section, index) => ({
      id: section.id,
      heading: section.heading,
      visual: {image: args.images[index % args.images.length]},
      narration: [{id: section.id, text: section.body}],
    })),
  };

  const outPath = path.resolve(args.out ?? path.join(outDir, "lesson.json"));
  await mkdir(path.dirname(outPath), {recursive: true});
  await writeFile(`${outPath}`, `${JSON.stringify(episodeJson, null, 2)}\n`, "utf8");
  const words = parsed.sections.reduce(
    (total, section) => total + section.body.split(/\s+/).length,
    0,
  );
  console.log(
    `Wrote ${path.relative(process.cwd(), outPath)}: ` +
      `${parsed.sections.length} blocks (${parsed.sections[0].id}..${parsed.sections.at(-1).id}), ~${words} words.`,
  );
}

try {
  await main();
} catch (error) {
  console.error(error.message);
  process.exitCode = 1;
}
